import{_ as a,o as i,a as t,b as l}from"./app.C41L12d5.js";const n="/ascendc.github.io/assets/nd2nz_new_1.BT3xwzwJ.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"多核非对齐切分","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/multi_core_unaligned_split"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/multi_core_unaligned_split.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/multi_core_unaligned_split.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1786954352000}'),r={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/multi_core_unaligned_split.md"};function s(_,e,o,p,c,d){return i(),t("div",null,[...e[0]||(e[0]=[l('<div><article class="markdown-body"><h1>多核非对齐切分<span id="ZH-CN_TOPIC_0000002500548096"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002264134828_section310824820358"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>多核场景，对矩阵进行切分时，若M、N、K无法整除singleCoreM 、singleCoreN、 singleCoreK时，就会出现尾块，即多核非对齐场景。如下图矩阵A、B的最后一行和最后一列的矩阵块：</p><p><img src="'+n+`" alt></p><p>此时，C矩阵中的R矩阵块，依然是通过A1*B1+A2*B2+A3*B3+A4*B4累加得到的，处理A1*B1、A2*B2、A3*B3、A4*B4等尾块时，需在kernel侧设置尾块大小，在不改变原有tiling的情况下，调用<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/SetTail.html">SetTail</a>接口重新设置本次计算的singleCoreM/singleCoreN/singleCoreK，在处理尾块的时候按照设置的值也就是tailM/tailN/tailK进行搬运和计算。</p><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002264134828_section118051016163613"></span><a class="header-anchor" href="#使用场景">​</a></h2><p>多核处理Matmul矩阵计算，存在尾块的场景。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002264134828_section14160134220363"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>处理尾块调用的SetTail接口，需要在Iterate/IterateAll之前调用。</p><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002264134828_section15486294368"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>Matmul多核非对齐场景的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_multi_core_unaligned">Matmul多核非对齐切分算子样例</a>。该场景的关键代码示例如下。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 处理尾块
int tailM = tiling.M - mCoreIndex * tiling.singleCoreM;
tailM = tailM &lt; tiling.singleCoreM ? tailM : tiling.singleCoreM;
int tailN = tiling.N - nCoreIndex * tiling.singleCoreN;
tailN = tailN &lt; tiling.singleCoreN ? tailN : tiling.singleCoreN;
// 当tailM &lt; singleCoreM或tailN &lt; singleCoreN时被认为需要处理尾块，此时可以调用SetTail接口进行设置
if (tailM &lt; tiling.singleCoreM || tailN &lt; tiling.singleCoreN) {
    matmulObj.SetTail(tailM, tailN);
}
</code></pre></div></article></div>`,1)])])}const u=a(r,[["render",s]]);export{g as __pageData,u as default};
